CREATE TABLE transaction_log (log_id SERIAL PRIMARY KEY, fan_registry TEXT, member_reg BIGINT, spend_amount NUMERIC, migration_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

INSERT INTO transaction_log (fan_registry, member_reg, spend_amount)
SELECT f.user_registry, m.member_reg, m.spend_usd::numeric
FROM membershipandspending m
JOIN fans f ON m.member_fan_pivot = f.user_registry
WHERE f.reg_moment < DATE_TRUNC('year', CURRENT_DATE)::text - INTERVAL '1 year';

SELECT COUNT(*) FROM transaction_log;

